#!/usr/bin/env node
/**
 * Generates the reference files of the `mod-ui-html` skill from the HTML/CSS design
 * system (the `design-system/` folder at the root of the mod-library repository):
 * one file per component page with its class table and example markup, an index,
 * and the design tokens.
 *
 *   node tools/gen-html-skill-reference.mjs [path/to/design-system]
 *
 * The path defaults to ../design-system (the repository layout). Do not edit the
 * generated files by hand: change the design-system pages and run this again.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseFragment, serializeOuter } from 'parse5';
import postcss from 'postcss';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const ds = resolve(process.argv[2] ?? join(root, '..', 'design-system'));
if (!existsSync(join(ds, 'components'))) {
  console.error(`html skill reference: no design system at ${ds} (pass its path as the first argument)`);
  process.exit(1);
}
const outDir = join(root, 'claude-plugin/skills/mod-ui-html/references');
const compOut = join(outDir, 'components');
mkdirSync(compOut, { recursive: true });

// Pages that document the system itself rather than a component.
const SKIP = new Set(['classes', 'components-overview', 'styles']);
// Pages whose whole body is one complete screen.
const SCREENS = new Set(['service-page', 'form-template', 'screens']);

const header = (title) =>
  `<!-- GENERATED by tools/gen-html-skill-reference.mjs from design-system/. Do not edit by hand. -->\n\n# ${title}\n\n`;
const oneLine = (s) => s.replace(/\s+/g, ' ').trim();
const cell = (s) => oneLine(s).replace(/\|/g, '\\|');

// --- tiny DOM helpers over the parse5 tree ---
const classes = (n) => (n.attrs?.find((a) => a.name === 'class')?.value ?? '').split(/\s+/);
const hasClass = (n, c) => classes(n).includes(c);
const kids = (n) => n.childNodes ?? [];
function* all(n) {
  for (const k of kids(n)) {
    yield k;
    yield* all(k);
  }
}
const find = (n, pred) => {
  for (const k of all(n)) if (pred(k)) return k;
  return undefined;
};
const findAll = (n, pred) => [...all(n)].filter(pred);
const text = (n) => (n ? (n.nodeName === '#text' ? n.value : kids(n).map(text).join('')) : '');
const byClass = (c) => (n) => n.tagName && hasClass(n, c);
const remove = (n) => {
  const p = n.parentNode;
  p.childNodes.splice(p.childNodes.indexOf(n), 1);
};
const inner = (n) =>
  kids(n)
    .filter((k) => k.nodeName !== '#comment')
    .map((k) => (k.nodeName === '#text' ? k.value : serializeOuter(k)))
    .join('');

// Strip blank lines at the ends and the common indentation.
const dedent = (s) => {
  const lines = s.replace(/\r/g, '').split('\n');
  while (lines.length && !lines[0].trim()) lines.shift();
  while (lines.length && !lines.at(-1).trim()) lines.pop();
  const ind = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)[0].length));
  return lines.map((l) => l.slice(Number.isFinite(ind) ? ind : 0)).join('\n');
};

const tableToMd = (table) => {
  const rows = findAll(table, (n) => n.tagName === 'tr').map((tr) =>
    kids(tr)
      .filter((c) => c.tagName === 'td' || c.tagName === 'th')
      .map((c) => {
        const code = find(c, (n) => n.tagName === 'code');
        const t = cell(text(c));
        return code && oneLine(text(code)) === oneLine(text(c)) ? `\`${t}\`` : t;
      }),
  );
  if (!rows.length) return '';
  const [head, ...body] = rows;
  return `| ${head.join(' | ')} |\n| ${head.map(() => '---').join(' | ')} |\n` + body.map((r) => `| ${r.join(' | ')} |`).join('\n');
};

// Public classes of the component's JS module (managers that wire up behaviour).
const jsInfo = (id) => {
  const file = join(ds, 'js/components', `${id}.js`);
  if (!existsSync(file)) return null;
  const src = readFileSync(file, 'utf8');
  // Classes named *Demo* or *Showcase* only drive the documentation page.
  const managers = [...src.matchAll(/^class (\w+)/gm)].map((m) => m[1]).filter((c) => !/Demo|Showcase/.test(c));
  if (!managers.length) return null;
  const data = [...new Set([...src.matchAll(/\[(data-[a-z-]+)/g)].map((m) => m[1]))].filter((d) => d !== 'data-toggle');
  return { rel: `js/components/${id}.js`, managers, data };
};

const pages = readdirSync(join(ds, 'components'), { withFileTypes: true })
  .filter((d) => d.isDirectory() && !SKIP.has(d.name) && existsSync(join(ds, 'components', d.name, `${d.name}.html`)))
  .map((d) => d.name)
  .sort();

const index = [];
for (const id of pages) {
  const html = readFileSync(join(ds, 'components', id, `${id}.html`), 'utf8');
  const doc = parseFragment(html);
  const title = oneLine(text(find(doc, byClass('content-title')))) || id;
  const description = oneLine(text(find(doc, byClass('content-description'))));
  for (const n of findAll(doc, (n) => n.tagName && (hasClass(n, 'live-demo') || hasClass(n, 'live-demo__heading')))) remove(n);
  const hdr = find(doc, byClass('content-header'));
  if (hdr) remove(hdr);
  // Documentation-only parts inside examples: drop labels, unwrap layout rows/grids.
  for (const n of findAll(doc, (n) => n.tagName && hasClass(n, 'showcase-label'))) remove(n);
  for (const n of findAll(doc, (n) => n.tagName && classes(n).some((c) => /^showcase-(row|grid|column|col|stack|group)/.test(c)))) {
    const p = n.parentNode;
    const i = p.childNodes.indexOf(n);
    for (const k of kids(n)) k.parentNode = p;
    p.childNodes.splice(i, 1, ...kids(n));
  }

  const parts = [];
  const sections = findAll(doc, byClass('showcase-section'));
  if (sections.length) {
    for (const s of sections) {
      const h = oneLine(text(find(s, byClass('showcase-title'))));
      const d = oneLine(text(find(s, byClass('showcase-description'))));
      const tables = findAll(s, (n) => n.tagName === 'table');
      const previews = findAll(s, byClass('showcase-preview'));
      let body = '';
      if (tables.length) body += tables.map(tableToMd).join('\n\n') + '\n\n';
      for (const p of previews) body += '```html\n' + dedent(inner(p)) + '\n```\n\n';
      if (body) parts.push(`## ${h}\n\n${d ? d + '\n\n' : ''}${body}`);
    }
  } else {
    const previews = findAll(doc, byClass('component-preview'));
    if (previews.length && !SCREENS.has(id)) {
      for (const p of previews) {
        const t = find(p, byClass('component-preview-title'));
        const h = oneLine(text(t)) || title;
        if (t) remove(t);
        const body = dedent(inner(p));
        if (body.trim()) parts.push(`## ${h}\n\n` + '```html\n' + body + '\n```\n\n');
      }
    } else {
      const body = dedent(inner(doc));
      if (body.trim()) parts.push('## Complete markup\n\n```html\n' + body + '\n```\n\n');
    }
  }

  const css = existsSync(join(ds, 'components', id, `${id}.css`)) ? `components/${id}/${id}.css` : null;
  const js = jsInfo(id);
  const empty = !parts.length;
  let out = header(title) + (description ? description + '\n\n' : '');
  out += `**Stylesheet:** ${css ? `\`${css}\`` : 'none of its own (uses the base and token stylesheets)'}\n\n`;
  if (js) {
    out +=
      `**Behaviour:** \`${js.rel}\`` +
      (js.managers.length ? ` (classes ${js.managers.map((m) => `\`${m}\``).join(', ')})` : '') +
      (js.data.length ? `; wired through ${js.data.map((d) => `\`[${d}]\``).join(', ')}` : '') +
      '. Without it the markup renders but does not open, close or toggle.\n\n';
  }
  if (empty) out += 'The design-system page builds this component with JavaScript, so there is no static example. Read the behaviour file above for the markup it creates.\n';
  else out += 'Layout wrappers named `showcase-*` belong to the documentation page, not to the component: leave them out.\n\n' + parts.join('');
  writeFileSync(join(compOut, `${id}.md`), out.trimEnd() + '\n');
  index.push(`| ${cell(title)} | \`components/${id}.md\` | ${css ? `\`${css}\`` : '—'} | ${js ? 'yes' : '—'} | ${cell(description).slice(0, 220)} |`);
}
for (const f of readdirSync(compOut)) if (!pages.includes(f.replace(/\.md$/, ''))) rmSync(join(compOut, f));

writeFileSync(
  join(outDir, 'component-index.md'),
  header('MOD HTML design system: component index') +
    'One line per component page. Open the file in `components/` for its classes and example markup. "JS" means the component needs its behaviour script.\n\n' +
    '| Component | File | Stylesheet | JS | What it is |\n| --- | --- | --- | --- | --- |\n' +
    index.join('\n') +
    '\n',
);

// Tokens: the semantic layer (css/tokens.css) and the raw DGA scales (utilities/DGATheme.css).
const tokenRows = [];
const seen = new Set();
const addToken = (prop, value, rel) => {
  if (seen.has(prop)) return;
  seen.add(prop);
  tokenRows.push(`| \`${prop}\` | \`${cell(value)}\` | ${rel} |`);
};
postcss.parse(readFileSync(join(ds, 'css/tokens.css'), 'utf8')).walkRules((rule) => {
  if (!rule.selectors.some((s) => s.trim() === ':root') || rule.parent?.type === 'atrule') return;
  rule.walkDecls(/^--/, (d) => addToken(d.prop, d.value, 'css/tokens.css'));
});
// The vendored DGA theme is not clean enough for a CSS parser: scan its first :root block.
{
  const src = readFileSync(join(ds, 'utilities/DGATheme.css'), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const block = /:root\s*\{([^}]*)\}/.exec(src)?.[1] ?? '';
  for (const m of block.matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g)) addToken(m[1], m[2].trim(), 'utilities/DGATheme.css');
}
writeFileSync(
  join(outDir, 'tokens.md'),
  header('MOD HTML design system: tokens') +
    'CSS custom properties. Prefer the semantic `--color-*`, `--spacing-*` and `--radius-*` names from `css/tokens.css`; the raw scales (`--sa-*`, `--gray-*`) come from `utilities/DGATheme.css`. Dark mode (`css/dark-mode.css`) overrides many, so reference the variable, never its value.\n\n' +
    '| Token | Value | Defined in |\n| --- | --- | --- |\n' +
    tokenRows.join('\n') +
    '\n',
);

// Icon names, grouped by category stylesheet.
const iconDir = join(ds, 'utilities/Icons_Css');
let iconCount = 0;
const iconGroups = (existsSync(iconDir) ? readdirSync(iconDir) : [])
  .filter((f) => f.endsWith('.css'))
  .sort()
  .map((f) => {
    const names = [...new Set([...readFileSync(join(iconDir, f), 'utf8').matchAll(/\.dga-icon-([a-z0-9-]+)::?before/g)].map((m) => m[1]))].sort();
    iconCount += names.length;
    return names.length ? `## ${f.replace(/\.css$/, '')}\n\n${names.join(' ')}\n` : '';
  })
  .filter(Boolean);
writeFileSync(
  join(outDir, 'icons.md'),
  header('MOD HTML design system: icon names') +
    `${iconCount} icons. Write \`<span class="dga-icon-NAME" aria-hidden="true"></span>\` with a name exactly as listed (search for a word: \`delete\`, \`calendar\`, \`user\`). An unknown name renders nothing. Needs \`css/icons-fonts.css\`.\n\n` +
    iconGroups.join('\n'),
);

console.log(`html skill reference: ${pages.length} component pages, ${tokenRows.length} tokens, ${iconCount} icons -> ${relative(root, outDir)}`);
